    for n, points in inputs:
        points.sort(key=lambda x: (x[0], -x[1]))
        if n == 3:
            s = 0
            for i in range(1, n):
                s += (points[i-1][0] - points[i][0]) * (points[i-1][1] + points[i][1])
            if s > 0:
                result.append(1)
            elif s < 0:
                result.append(-1)
            else:
                result.append(0)
        elif n == 4:
            yes = 0
            for i in range(1, n):
                x0, y0 = points[i-1]
                x1, y1 = points[i]
                x = (x0 * y1 - x1 * y0) / (x0 - x1)
                y = (x0 * y1 - x1 * y0) / (y0 - y1)
                if x >= 0 and y >= 0:
                    yes += 1
            if yes % 2 == 1:
                result.append(1)
            else:
                result.append(0)
        else:
            result.append(0)
    return result
